             return (
               <Link 
                 key={item.path} 
                 to={item.path}
                 className={`flex-1 flex flex-col items-center justify-center py-3 relative group transition-all duration-300 ${isActive ? '-translate-y-1' : ''}`}
               >
                  {/* Active Indicator Pulse */}
                  {isActive && (
                    <div className="absolute -top-1 w-12 h-1 bg-brand-accent rounded-b-full shadow-[0_0_15px_#ff4655] animate-pulse"></div>
                  )}

                  <item.icon 
                    size={20} 
                    className={`mb-1 transition-all duration-300 ${isActive ? 'text-brand-accent drop-shadow-[0_0_8px_rgba(255,70,85,0.8)] scale-110' : 'text-slate-500 group-hover:text-white'}`} 
                  />
                  <span className={`text-[9px] font-bold uppercase tracking-widest transition-colors ${isActive ? 'text-white' : 'text-slate-600'}`}>
                    {item.label}
                  </span>
               </Link>
             );
           })}
        </div>
      </div>

    </div>
  );
};

