import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Search, X, ArrowRight } from 'lucide-react';

interface SkinSearchFloatingBarProps {
  isHomePage: boolean;
}

const SkinSearchFloatingBar: React.FC<SkinSearchFloatingBarProps> = ({ isHomePage }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const [query, setQuery] = useState('');
  const [isFocused, setIsFocused] = useState(false);
  const [arrivalPulse, setArrivalPulse] = useState(false);
  const prevIsHome = useRef(isHomePage);

  // Trigger a pulse effect when the bar finishes docking into the header
  useEffect(() => {
    if (prevIsHome.current && !isHomePage) {
      setArrivalPulse(true);
      const timer = setTimeout(() => setArrivalPulse(false), 1000);
      return () => clearTimeout(timer);
    }
    prevIsHome.current = isHomePage;
  }, [isHomePage]);

  // Sync with URL query param if present
  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const q = params.get('q');
    if (q) setQuery(q);
  }, [location.search]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim()) {
      navigate(`/browse?q=${encodeURIComponent(query.trim())}`);
      setIsFocused(false);
      const activeElement = document.activeElement as HTMLElement;
      if (activeElement) activeElement.blur();
    }
  };

  const handleClear = () => {
      setQuery('');
      navigate('/browse');
  };

  const mode = isHomePage ? 'hero' : 'header';

  return (
    <>
        {/* Backdrop - Only when focused */}
        <div 
            className={`fixed inset-0 bg-black/60 backdrop-blur-[6px] z-[55] transition-all duration-700 ${isFocused ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
            onClick={() => setIsFocused(false)}
        />

        {/* Floating Bar Container */}
        <div 
            className={`${isFocused ? 'fixed' : 'absolute'} z-[60] transition-all duration-[850ms] ease-[cubic-bezier(0.34,1.56,0.64,1)] will-change-transform
                ${isFocused 
                    ? 'top-28 md:top-40 left-1/2 -translate-x-1/2 w-[calc(100%-1.5rem)] md:w-[600px] scale-100' 
                    : mode === 'hero'
                        ? 'top-48 md:top-80 left-1/2 -translate-x-1/2 w-[calc(100%-4rem)] max-w-[320px] md:w-fit scale-100'
                        : 'top-4 right-3 md:right-8 w-fit translate-x-0 scale-90 md:scale-100'
                }
            `}
        >
            {/* Arrival Pulse Glow (Header Mode Only) */}
            {arrivalPulse && !isHomePage && (
              <div className="absolute inset-0 bg-brand-cyan/40 rounded-full animate-ping pointer-events-none"></div>
            )}

            <div className={`transition-all duration-500 ${!isFocused && mode === 'hero' ? 'animate-float' : ''}`}>
                {/* Visual Glow Layer */}
                <div className={`absolute inset-0 rounded-full blur-2xl transition-all duration-700 
                  ${isFocused 
                    ? 'bg-brand-cyan/20 opacity-100 scale-110' 
                    : mode === 'hero' 
                      ? 'bg-brand-accent/20 opacity-60 scale-90' 
                      : 'bg-brand-cyan/0 opacity-0'
                  }`} 
                />

                <form 
                    onSubmit={handleSearch}
                    onClick={() => !isFocused && setIsFocused(true)}
                    className={`relative flex items-center bg-brand-darker/80 backdrop-blur-2xl border rounded-full shadow-[0_15px_50px_rgba(0,0,0,0.6)] overflow-hidden transition-all duration-[850ms] ease-[cubic-bezier(0.34,1.56,0.64,1)] cursor-text group
                        ${isFocused 
                            ? 'w-full ring-2 ring-brand-cyan/40 py-3 md:py-5 px-4 md:px-7 border-brand-cyan/40' 
                            : mode === 'hero'
                                ? 'w-full md:w-[320px] py-3 md:py-4 px-4 md:px-6 border-white/10 hover:border-brand-accent/40 hover:shadow-[0_0_25px_rgba(255,70,85,0.3)]'
                                : 'w-[40px] h-[40px] md:w-[44px] md:h-[44px] py-0 px-0 justify-center hover:bg-white/10 border-white/5 bg-black/40'
                        }
                    `}
                >
                    {/* Cyber Grid Pattern Background (Visible when focused) */}
                    <div className={`absolute inset-0 opacity-10 pointer-events-none transition-opacity duration-700 ${isFocused ? 'opacity-20' : 'opacity-0'}`} 
                         style={{ backgroundImage: 'radial-gradient(circle at 1px 1px, #00f0ff 1px, transparent 0)', backgroundSize: '16px 16px' }} />

                    {/* Search Icon */}
                    <div className={`flex items-center justify-center transition-all duration-[850ms] ${isFocused ? 'mr-3 md:mr-5 scale-110 rotate-90' : (mode === 'hero' ? 'mr-2 md:mr-3 rotate-0' : 'mr-0 rotate-0')}`}>
                         <div className={`transition-all duration-500 p-1.5 md:p-2 rounded-full ${isFocused ? 'bg-brand-cyan/20 text-brand-cyan' : 'bg-transparent text-slate-400 group-hover:text-white'}`}>
                             <Search className={`${mode === 'header' && !isFocused ? 'w-4 h-4 md:w-5 md:h-5' : 'w-5 h-5 md:w-6 md:h-6'}`} strokeWidth={2.5} />
                         </div>
                    </div>

                    {/* Input Field */}
                    <input 
                        name="skin-search"
                        type="text" 
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                        onFocus={() => setIsFocused(true)}
                        placeholder="Search Skins..."
                        autoComplete="off"
                        className={`bg-transparent border-none outline-none text-white placeholder-slate-500 font-display font-bold text-base md:text-lg tracking-wide transition-all duration-[850ms]
                            ${isFocused 
                                ? 'flex-1 opacity-100' 
                                : mode === 'hero'
                                    ? 'flex-1 opacity-100 md:w-48 cursor-text'
                                    : 'hidden'
                            }
                        `}
                    />

                    {/* Actions / Submit */}
                    <div className={`flex items-center gap-2 md:gap-3 transition-all duration-500 ${isFocused || (mode === 'hero' && query) ? 'opacity-100 translate-x-0' : 'opacity-0 translate-x-10 w-0'}`}>
                        {query && isFocused && (
                            <button 
                                type="button"
                                onClick={(e) => { e.stopPropagation(); handleClear(); }}
                                className="p-1.5 md:p-2 hover:bg-white/10 rounded-full text-slate-500 hover:text-white transition-all hover:scale-110"
                            >
                                <X className="w-4 h-4 md:w-5 md:h-5" />
                            </button>
                        )}

                        {isFocused && (
                            <button 
                                type="submit"
                                className="bg-brand-cyan hover:bg-white text-brand-darker rounded-full p-2 md:p-2.5 shadow-[0_0_20px_rgba(0,240,255,0.4)] transition-all hover:scale-110 active:scale-95"
                            >
                                <ArrowRight className="w-4 h-4 md:w-5 md:h-5" strokeWidth={3} />
                            </button>
                        )}
                    </div>

                    <div className={`absolute top-0 left-0 w-full h-[2px] bg-brand-cyan/30 transition-opacity duration-700 pointer-events-none ${isFocused ? 'opacity-100 animate-scan' : 'opacity-0'}`}></div>
                    <div className={`absolute bottom-0 left-0 h-[2px] bg-gradient-to-r from-transparent via-brand-cyan to-transparent w-full transition-all duration-1000 ${isFocused ? 'opacity-100 translate-x-0' : 'opacity-0 -translate-x-full'}`}></div>
                </form>
            </div>
        </div>
    </>
  );
};

export default SkinSearchFloatingBar;

import React, { useState, useEffect, useRef } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { UserCog, Home, Gamepad2, User as UserIcon, LogOut, LayoutDashboard, Zap, Award, Sparkles, X, Trophy, Shield } from 'lucide-react';
import { StorageService, DEFAULT_HOME_CONFIG, SITE_LOGO_URL } from '../services/storage';
import { User, HomeConfig } from '../types';
import SkinSearchFloatingBar from './SkinSearchFloatingBar';

const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [showProfileMenu, setShowProfileMenu] = useState(false);
  const [showBonusPopup, setShowBonusPopup] = useState(false);
  const [prevPoints, setPrevPoints] = useState<number | null>(null);
  const [pointDiff, setPointDiff] = useState<number | null>(null);
  const [scrolled, setScrolled] = useState(false);
  const [homeConfig, setHomeConfig] = useState<HomeConfig>(DEFAULT_HOME_CONFIG);

  const isHomePage = location.pathname === '/';

  // SCROLL TO TOP LOGIC
  useEffect(() => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  }, [location.pathname]);

  // SCROLL LISTENER FOR HEADER
  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const loadConfig = async () => {
    try {
      const config = await StorageService.getHomeConfig();
      setHomeConfig(config);
    } catch (err) {}
  };

  const syncData = () => {
    const user = StorageService.getCurrentUser();

    // Animate point changes
    if (user && prevPoints !== null && user.ultraPoints > prevPoints) {
      const diff = user.ultraPoints - prevPoints;
      setPointDiff(diff);
      setTimeout(() => setPointDiff(null), 4000);
    }

    setCurrentUser(user);
    if (user) setPrevPoints(user.ultraPoints);

    loadConfig();

    // Show bonus popup if user has exactly 20 points (newly registered) and hasn't seen it this session
    if (user && user.ultraPoints === 20 && !sessionStorage.getItem('bonus_shown')) {
      setShowBonusPopup(true);
      sessionStorage.setItem('bonus_shown', 'true');
    }
  };

  useEffect(() => {
    syncData();
    // Run expiration check immediately on load
    StorageService.checkExpiredBookings();

    // Set up interval to check for expired bookings every minute
    const expiryInterval = setInterval(() => {
        StorageService.checkExpiredBookings();
    }, 60000);

    const unsubscribe = StorageService.subscribe(() => {
      syncData();
    });
    window.addEventListener('storage', syncData);
    return () => {
      clearInterval(expiryInterval);
      unsubscribe();
      window.removeEventListener('storage', syncData);
    };
  }, [location.pathname]);

  const handleLogout = () => {
    StorageService.logoutUser();
    setCurrentUser(null);
    setShowProfileMenu(false);
    navigate('/');
  };

  const isActive = (path: string) => location.pathname === path;

  // Mobile Navigation Items
  const mobileNavItems = [
    { label: 'Home', path: '/', icon: Home },
    { label: 'Rent', path: '/browse', icon: Gamepad2 },
    { label: currentUser ? 'Profile' : 'Login', path: currentUser ? '/dashboard' : '/login', icon: currentUser ? UserIcon : UserIcon },
  ];

  return (
    <div className="min-h-screen bg-brand-darker text-slate-100 font-sans flex flex-col selection:bg-brand-accent selection:text-white relative">

      {/* TOP MARQUEE (As requested in image) */}
      <div className="bg-black/40 border-b border-white/5 backdrop-blur-sm relative z-[60] overflow-hidden h-8 flex items-center">
         <div className="animate-marquee whitespace-nowrap flex items-center gap-8 text-[10px] font-bold tracking-[0.2em] text-slate-400 uppercase w-full">
            <span className="flex items-center gap-2"><Zap size={10} className="text-yellow-400" /> NEW RADIANT BUNDLES ADDED TO INVENTORY</span>
            <span className="flex items-center gap-2 text-brand-accent">⚡ GET 10% OFF ON ALL 24-HOUR RENTALS</span>
            <span className="flex items-center gap-2"><Shield size={10} className="text-green-400" /> VANGUARD BYPASS SECURED - 0% BAN RATE</span>
            <span className="flex items-center gap-2"><Zap size={10} className="text-yellow-400" /> NEW RADIANT BUNDLES ADDED TO INVENTORY</span>
         </div>
      </div>

      {/* Point Earned Floating Animation */}
      {pointDiff !== null && (
        <div className="fixed top-24 right-4 md:right-12 z-[100] pointer-events-none animate-in fade-in slide-in-from-bottom-4 duration-700">
           <div className="flex items-center gap-2 bg-yellow-500/20 backdrop-blur-md border border-yellow-500/50 px-4 py-2 rounded-full shadow-[0_0_30px_rgba(234,179,8,0.4)]">
              <Sparkles className="text-yellow-400 w-5 h-5 animate-spin-slow" />
              <span className="text-yellow-400 font-black text-xl">+{pointDiff} UP</span>
           </div>
        </div>
      )}

      {/* Bonus Popup */}
      {showBonusPopup && (
         <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/80 backdrop-blur-sm animate-in fade-in duration-300">
            <div className="bg-brand-surface border border-yellow-500/30 rounded-2xl p-8 max-w-sm relative text-center shadow-[0_0_50px_rgba(234,179,8,0.2)]">
               <button onClick={() => setShowBonusPopup(false)} className="absolute top-4 right-4 text-slate-500 hover:text-white"><X size={20} /></button>
               <div className="w-20 h-20 bg-yellow-500/20 rounded-full flex items-center justify-center mx-auto mb-6 animate-bounce">
                  <Award size={40} className="text-yellow-500" />
               </div>
               <h3 className="text-2xl font-black text-white italic uppercase mb-2">Welcome Bonus!</h3>
               <p className="text-slate-400 mb-6">You've received <span className="text-yellow-500 font-bold">20 Ultra Points</span> for joining the elite.</p>
               <button onClick={() => setShowBonusPopup(false)} className="w-full py-3 bg-yellow-500 hover:bg-yellow-400 text-brand-darker font-black uppercase tracking-widest rounded-lg">Claim Reward</button>
            </div>
         </div>
      )}

      {/* DESKTOP & MOBILE NAVIGATION BAR */}
      <header 
        className={`absolute top-8 left-0 right-0 z-50 transition-all duration-500 
        ${scrolled 
          ? 'bg-brand-darker/90 backdrop-blur-xl border-b border-white/10 py-3 shadow-[0_10px_30px_rgba(0,0,0,0.5)]' 
          : 'bg-transparent border-b border-transparent py-4'
        }`}
      >
        <div className="max-w-7xl mx-auto px-4 flex items-center justify-center md:justify-between relative">

           {/* Mobile: Centered Logo exactly like image */}
           {/* Desktop: Logo Left */}
           <Link to="/" className="flex items-center gap-3 group relative z-10">
              <Shield className="w-6 h-6 md:w-8 md:h-8 text-brand-accent fill-transparent stroke-[2px]" />
              <div>
                 <h1 className="font-display font-black text-xl md:text-2xl tracking-tighter uppercase italic leading-none text-white">
                    KRISHNA <span className="text-brand-accent">VALO STORE</span>
                 </h1>
              </div>
              {/* Tooltip */}
              <span className="absolute top-full mt-4 left-0 px-3 py-1 bg-brand-darker/95 backdrop-blur-md border border-white/10 text-brand-cyan text-[10px] font-bold uppercase tracking-widest rounded opacity-0 group-hover:opacity-100 transition-all duration-300 transform group-hover:translate-y-0 -translate-y-2 pointer-events-none shadow-xl whitespace-nowrap hidden md:block">
