import React, { useState, useEffect } from 'react';
import { Navigate, useNavigate } from 'react-router-dom';
import { StorageService } from '../services/storage';
import { User, Booking, BookingStatus, Account } from '../types';
import { 
  User as UserIcon, Clock, History, LifeBuoy, LogOut, 
  Gamepad2, Calendar, Copy, Eye, EyeOff, ShieldCheck, 
  AlertTriangle, ChevronRight, CheckCircle2, MessageCircle, Award, Gift, Gem, Sparkles, Lock, Timer
} from 'lucide-react';

const UserDashboard: React.FC = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<'overview' | 'rentals' | 'history' | 'profile' | 'support' | 'rewards'>('overview');
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);

  // Load user data
  useEffect(() => {
    const loadData = async () => {
      const currentUser = StorageService.getCurrentUser();
      if (currentUser) {
        setUser(currentUser);
        const userBookings = await StorageService.getUserBookings(currentUser.id);
        userBookings.sort((a, b) => {
          if ((a.status === BookingStatus.ACTIVE || a.status === BookingStatus.PRE_BOOKED) && (b.status !== BookingStatus.ACTIVE && b.status !== BookingStatus.PRE_BOOKED)) return -1;
          if ((a.status !== BookingStatus.ACTIVE && a.status !== BookingStatus.PRE_BOOKED) && (b.status === BookingStatus.ACTIVE || b.status === BookingStatus.PRE_BOOKED)) return 1;
          return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
        });
        setBookings(userBookings);
      }
      setLoading(false);
    };
    loadData();

    const unsubscribe = StorageService.subscribe(loadData);
    return () => { unsubscribe(); };
  }, []);

  const handleLogout = () => {
    StorageService.logoutUser();
    navigate('/');
  };

  if (loading) return null;
  if (!user) return <Navigate to="/login" />;

  const activeBookings = bookings.filter(b => b.status === BookingStatus.ACTIVE || b.status === BookingStatus.PENDING || b.status === BookingStatus.PRE_BOOKED);
  const pastBookings = bookings.filter(b => b.status === BookingStatus.COMPLETED || b.status === BookingStatus.CANCELLED);

  const renderTabContent = () => {
    switch (activeTab) {
      case 'overview':
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
            {/* Ultra Points Hero */}
            <div className="bg-gradient-to-br from-yellow-600/20 to-brand-surface border border-yellow-500/30 rounded-2xl p-6 relative overflow-hidden group">
               <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:opacity-20 transition-opacity">
                  <Award size={120} className="text-yellow-500 rotate-12" />
