const UserDashboard: React.FC = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<'overview' | 'rentals' | 'history' | 'profile' | 'support' | 'rewards'>('overview');
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);

  // Load user data
  useEffect(() => {
    const loadData = async () => {
      const currentUser = StorageService.getCurrentUser();
      if (currentUser) {
        setUser(currentUser);
        const userBookings = await StorageService.getUserBookings(currentUser.id);
        userBookings.sort((a, b) => {
          if ((a.status === BookingStatus.ACTIVE || a.status === BookingStatus.PRE_BOOKED) && (b.status !== BookingStatus.ACTIVE && b.status !== BookingStatus.PRE_BOOKED)) return -1;
          if ((a.status !== BookingStatus.ACTIVE && a.status !== BookingStatus.PRE_BOOKED) && (b.status === BookingStatus.ACTIVE || b.status === BookingStatus.PRE_BOOKED)) return 1;
          return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
        });
        setBookings(userBookings);
      }
      setLoading(false);
    };
    loadData();

    const unsubscribe = StorageService.subscribe(loadData);
    return () => { unsubscribe(); };
  }, []);

