import { 
  User as UserIcon, Clock, History, LifeBuoy, LogOut, 
  Gamepad2, Calendar, Copy, Eye, EyeOff, ShieldCheck, 
  AlertTriangle, ChevronRight, CheckCircle2, MessageCircle, Award, Gift, Gem, Sparkles, Lock, Timer, CalendarClock
