  User as UserIcon, Clock, History, LifeBuoy, LogOut,
} from 'react-feather';
import RentalCard from '../components/RentalCard';
import './UserDashboard.css';

interface UserDashboardProps {
  user: User | null;
  account: Account | null;
}

const UserDashboard: React.FC<UserDashboardProps> = ({ user, account }) => {
  const navigate = useNavigate();
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [activeBookings, setActiveBookings] = useState<Booking[]>([]);
  const [pastBookings, setPastBookings] = useState<Booking[]>([]);

  useEffect(() => {
    const fetchBookings = async () => {
      try {
        if (!user || !account) {
          navigate('/login');
          return;
        }

        const userBookings = await StorageService.getBookings(account.id);
        const sortedBookings = userBookings.sort((a, b) => {
          if (a.id === b.id) {
            return 0; // if the ids are same, return 0 to prevent issues
          }
          return a.id > b.id ? -1 : 1;
        });

        // Split bookings into active and past
        const now = new Date();
        const activeBookings = sortedBookings.filter(booking => new Date(booking.endDate) > now);
        const pastBookings = sortedBookings.filter(booking => new Date(booking.endDate) <= now);

        setActiveBookings(activeBookings);
        setPastBookings(pastBookings);
        setBookings(sortedBookings);

      } catch (error) {
        console.error('Error fetching bookings:', error);
      }
    };
    fetchBookings();
  }, [user, navigate, account]);

  const handleLogout = async () => {
    try {
      await StorageService.logout();
      navigate('/login');
    } catch (error) {
      console.error('Logout failed:', error);
    }
  };

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  return (
    <div className='UserDashboard'>
      <div className="dashboard-content">
