export const StorageService = {
  subscribe: (callback: StorageListener) => {
    listeners.add(callback);
    return () => listeners.delete(callback);
  },

  getAccounts: async (rankFilter?: string): Promise<Account[]> => {
    let query = getSupabase().from('accounts').select('*');
    if (rankFilter && rankFilter !== 'All') {
       query = query.eq('data->>rank', rankFilter);
    }
    const { data, error } = await query;
    if (error || !data) return [];
    return data.map(row => row.data as Account);
  },

  getAccountById: async (id: string): Promise<Account | undefined> => {
    const { data, error } = await getSupabase().from('accounts').select('data').eq('id', id).single();
    if (error || !data) return undefined;
    return data.data as Account;
  },

  saveAccount: async (account: Account) => {
    await getSupabase().from('accounts').upsert({ id: account.id, data: account });
    notifyStorageChange();
  },

  deleteAccount: async (id: string) => {
    await getSupabase().from('accounts').delete().eq('id', id);
    notifyStorageChange();
  },

  getBookings: async (accountId?: string): Promise<Booking[]> => {
    let query = getSupabase().from('bookings').select('*').order('data->createdAt', { ascending: false });
    const { data, error } = await query;
    if (error || !data) return [];

    let bookings = data.map(row => row.data as Booking);
    if (accountId) {
      bookings = bookings.filter(b => b.accountId === accountId);
    }
    return bookings;
  },

  getUserBookings: async (userId: string): Promise<Booking[]> => {
    const bookings = await StorageService.getBookings();
    return bookings.filter(b => b.customerId === userId);
  },

  checkAvailability: async (accountId: string, startTime: string, endTime: string): Promise<boolean> => {
    const bookings = await StorageService.getBookings(accountId);

    const newStart = new Date(startTime).getTime();
    const newEnd = new Date(endTime).getTime();

    const conflicts = bookings.filter(b => {
      // String literal comparison
      if (b.status === 'CANCELLED' || b.status === 'COMPLETED' || b.status === 'PENDING') return false;

      const bStart = new Date(b.startTime).getTime();
      const bEnd = new Date(b.endTime).getTime();

      return (newStart < bEnd && newEnd > bStart);
    });

    return conflicts.length === 0;
  },

  createBooking: async (booking: Booking) => {
    await getSupabase().from('bookings').upsert({ order_id: booking.orderId, data: booking, status: booking.status });
    notifyStorageChange();
  },

  updateBooking: async (booking: Booking) => {
    await getSupabase().from('bookings').update({ data: booking, status: booking.status }).eq('order_id', booking.orderId);
    notifyStorageChange();
  },

  deleteBooking: async (orderId: string) => {
    await getSupabase().from('bookings').delete().eq('order_id', orderId);
    notifyStorageChange();
  },

  updateBookingStatus: async (orderId: string, status: string) => {
    const { data: row } = await getSupabase().from('bookings').select('data').eq('order_id', orderId).single();

    if (row?.data) {
      const booking = row.data as Booking;
      const oldStatus = booking.status;

      if (oldStatus === status) return;

      booking.status = status;

      await getSupabase().from('bookings').update({ data: booking, status: status }).eq('order_id', orderId);

      if (booking.customerId) {
        const points = Math.floor(booking.totalPrice / 9);

        if (oldStatus === 'PENDING' && (status === 'ACTIVE' || status === 'PRE_BOOKED')) {
          await StorageService.updateUserPoints(booking.customerId, points);
        } 
        else if ((oldStatus === 'ACTIVE' || oldStatus === 'PRE_BOOKED') && status === 'CANCELLED') {
          await StorageService.updateUserPoints(booking.customerId, -points);
        }
      }

      const account = await StorageService.getAccountById(booking.accountId);

      if (account) {
        if (status === 'ACTIVE') {
          account.isBooked = true;
          account.bookedUntil = booking.endTime;
        } else if (status === 'COMPLETED' || status === 'CANCELLED') {
          if (account.isBooked && account.bookedUntil === booking.endTime) {
            account.isBooked = false;
            account.bookedUntil = null;
          }
        }
        await StorageService.saveAccount(account);
      }

      notifyStorageChange();
    }
  },

  syncBooking: async (orderId: string) => {
     try {
       const { data: row } = await getSupabase().from('bookings').select('data').eq('order_id', orderId).single();
       if (row?.data) {
         const booking = row.data as Booking;
         const now = Date.now();
         const startTime = new Date(booking.startTime).getTime();
         const endTime = new Date(booking.endTime).getTime();

         if (booking.status === 'PRE_BOOKED' && now >= startTime && now < endTime) {
           await StorageService.updateBookingStatus(orderId, 'ACTIVE');
           return true;
         }

         if (booking.status === 'ACTIVE' && now >= endTime) {
            await StorageService.updateBookingStatus(orderId, 'COMPLETED');
            return true;
         }
       }
       return false;
     } catch (e) {
       console.error("Sync error", e);
       return false;
     }
  },

  checkExpiredBookings: async () => {
    try {
      const bookings = await StorageService.getBookings();
      const now = new Date().getTime();
      let hasUpdates = false;

      for (const booking of bookings) {
        const endTime = new Date(booking.endTime).getTime();
        const startTime = new Date(booking.startTime).getTime();
        const createdAt = new Date(booking.createdAt).getTime();

        if (booking.status === 'ACTIVE' && endTime <= now) {
          await StorageService.updateBookingStatus(booking.orderId, 'COMPLETED');
          hasUpdates = true;
        }

        if (booking.status === 'PRE_BOOKED' && startTime <= now && endTime > now) {
          await StorageService.updateBookingStatus(booking.orderId, 'ACTIVE');
          hasUpdates = true;
        }

        if (booking.status === 'PENDING') {
           const tenMins = 10 * 60 * 1000;
           if (now - createdAt > tenMins) {
             await StorageService.deleteBooking(booking.orderId);
             hasUpdates = true;
           }
        }
      }

      if (hasUpdates) {
        notifyStorageChange();
      }
    } catch (e) {}
  },

  updateUserPoints: async (userId: string, amount: number) => {
    const { data: row } = await getSupabase().from('users').select('data').eq('id', userId).single();
    if (row?.data) {
      const userData = row.data as User;
      userData.ultraPoints = (userData.ultraPoints || 0) + amount;

      await getSupabase().from('users').update({ data: userData }).eq('id', userId);

      const currentUser = StorageService.getCurrentUser();
      if (currentUser && currentUser.id === userId) {
        localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(userData));
      }
      notifyStorageChange();
    }
  },

  getHomeConfig: async (): Promise<HomeConfig> => {
    try {
      const { data, error } = await getSupabase().from('home_config').select('data').eq('id', 'global').single();
      if (error || !data?.data) return DEFAULT_HOME_CONFIG;

      const config = data.data as HomeConfig;
      return {
        ...DEFAULT_HOME_CONFIG,
        ...config,
        trustItems: config.trustItems && config.trustItems.length > 0 ? config.trustItems : DEFAULT_HOME_CONFIG.trustItems,
        heroSlides: config.heroSlides && config.heroSlides.length > 0 ? config.heroSlides : DEFAULT_HOME_CONFIG.heroSlides,
        marqueeText: config.marqueeText && config.marqueeText.length > 0 ? config.marqueeText : DEFAULT_HOME_CONFIG.marqueeText,
        stepItems: config.stepItems && config.stepItems.length > 0 ? config.stepItems : DEFAULT_HOME_CONFIG.stepItems,
        reviews: config.reviews && config.reviews.length > 0 ? config.reviews : DEFAULT_HOME_CONFIG.reviews,
        ultraPoints: config.ultraPoints || DEFAULT_HOME_CONFIG.ultraPoints,
        cta: config.cta || DEFAULT_HOME_CONFIG.cta
      };
    } catch {
      return DEFAULT_HOME_CONFIG;
    }
  },

  saveHomeConfig: async (config: HomeConfig) => {
    const { error } = await getSupabase().from('home_config').upsert({ id: 'global', data: config });
    if (error) throw error;
    notifyStorageChange();
  },

  getCurrentUser: (): User | null => {
    const data = localStorage.getItem(CURRENT_USER_KEY);
    return data ? JSON.parse(data) : null;
  },

  logoutUser: () => {
    localStorage.removeItem(CURRENT_USER_KEY);
    notifyStorageChange();
  },

  getAllUsers: async (): Promise<User[]> => {
    const { data, error } = await getSupabase().from('users').select('data');
    if (error || !data) return [];
    return data.map(row => row.data as User);
  },

  deleteUser: async (userId: string) => {
    await getSupabase().from('users').delete().eq('id', userId);
    notifyStorageChange();
  },

  registerUser: async (name: string, email: string, phone: string, password: string): Promise<User> => {
    const newUser: User = {
      id: 'usr-' + Date.now(),
      name, email, phone, password,
      avatarUrl: `https://api.dicebear.com/7.x/avataaars/svg?seed=${name}`,
      role: 'customer',
      isVerified: true,
      ultraPoints: 20, 
      createdAt: new Date().toISOString(),
      lastLogin: new Date().toISOString()
    };
    await getSupabase().from('users').insert({ id: newUser.id, email: newUser.email, data: newUser });
    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(newUser));
    notifyStorageChange();
    return newUser;
  },

  loginUser: async (email: string, password: string): Promise<User> => {
    const { data, error } = await getSupabase().from('users').select('data').eq('email', email).single();
    if (error || !data) throw new Error("Invalid credentials");
    const user = data.data as User;
    if (user.password !== password) throw new Error("Invalid credentials");

    user.lastLogin = new Date().toISOString();
    await getSupabase().from('users').update({ data: user }).eq('id', user.id);

    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user));
    notifyStorageChange();
    return user;
  }
};

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Account, Booking } from '../types';
import { StorageService } from '../services/storage';
import { Trophy, Gem, Clock, CalendarDays, Sparkles } from 'lucide-react';

interface AccountCardProps {
  account: Account;
}

const AccountCard: React.FC<AccountCardProps> = ({ account }) => {
  const [timeLeft, setTimeLeft] = useState<string | null>(null);
  const [timerLabel, setTimerLabel] = useState<string>('Opens In');
  const [statusStyle, setStatusStyle] = useState<string>('text-brand-accent border-brand-accent/50 bg-brand-accent/20');

  const [isEffectivelyAvailable, setIsEffectivelyAvailable] = useState(!account.isBooked);
  const [upcomingBooking, setUpcomingBooking] = useState<Booking | null>(null);

  // Poll for upcoming bookings
  useEffect(() => {
    const fetchBookings = async () => {
       const allBookings = await StorageService.getBookings(account.id);
       const now = Date.now();

       // Find relevant booking (Active or Pre-Booked in future)
       // Using string literals for status
       const relevant = allBookings
          .filter(b => 
             (b.status === 'PRE_BOOKED' || b.status === 'ACTIVE') &&
             new Date(b.endTime).getTime() > now // Not expired
          )
          .sort((a, b) => new Date(a.startTime).getTime() - new Date(b.startTime).getTime())[0];

       setUpcomingBooking(relevant || null);
    };

    fetchBookings();
    const interval = setInterval(fetchBookings, 60000); // Update every minute
    return () => clearInterval(interval);
  }, [account.id]);

  // Timer Logic
  useEffect(() => {
    const updateTimer = () => {
      const now = new Date().getTime();
      let targetTime = 0;
      let label = 'Opens In';
      let style = 'text-brand-accent border-brand-accent/50 bg-brand-accent/20';
      let isAvailable = true;

      if (upcomingBooking) {
         const start = new Date(upcomingBooking.startTime).getTime();
         const end = new Date(upcomingBooking.endTime).getTime();

         if (now < start) {
            // PRE_BOOKED (Future)
            targetTime = start;
            label = 'Starts In';
            style = 'text-purple-400 border-purple-500/50 bg-purple-500/20';
            isAvailable = false;
         } else if (now < end) {
            // ACTIVE (Current)
            targetTime = end;
            label = 'Ends In';
            style = 'text-brand-accent border-brand-accent/50 bg-brand-accent/20';
            isAvailable = false;
         }
      } else if (account.isBooked && account.bookedUntil) {
         // Fallback for manually booked accounts without booking record
         targetTime = new Date(account.bookedUntil).getTime();
         isAvailable = false;
      }

      const diff = targetTime - now;

      if (diff > 0 && !isAvailable) {
        const h = Math.floor(diff / (1000 * 60 * 60));
        const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
        const s = Math.floor((diff % (1000 * 60)) / 1000);
        setTimeLeft(`${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`);
        setTimerLabel(label);
        setStatusStyle(style);
        setIsEffectivelyAvailable(false);
      } else {
        setTimeLeft(null);
        setIsEffectivelyAvailable(true);
      }
    };

    updateTimer();
    const interval = setInterval(updateTimer, 1000);
    return () => clearInterval(interval);
  }, [account.isBooked, account.bookedUntil, upcomingBooking]);

  const getRankColor = (rank: string) => {
    if (rank.includes('Gold')) return 'text-yellow-400';
    if (rank.includes('Platinum')) return 'text-cyan-400';
    if (rank.includes('Diamond')) return 'text-purple-400';
    if (rank.includes('Ascendant')) return 'text-emerald-400';
    if (rank.includes('Immortal')) return 'text-red-500';
    return 'text-slate-300';
  };

  const skinCount = account.totalSkins || account.skins.length;

  return (
    <div className={`group relative rounded-none overflow-hidden border transition-all duration-300 ${isEffectivelyAvailable ? 'border-white/10 bg-brand-surface hover:border-brand-accent/50 hover:shadow-[0_0_30px_rgba(255,70,85,0.15)] hover:-translate-y-2' : 'border-white/5 bg-brand-dark opacity-90'}`}>

      <Link to={`/account/${account.id}`} className="block h-full">
        {/* Corner Accents */}
        <div className="absolute top-0 left-0 w-2 h-2 border-l border-t border-white/20 group-hover:border-brand-accent transition-colors z-20"></div>
        <div className="absolute top-0 right-0 w-2 h-2 border-r border-t border-white/20 group-hover:border-brand-accent transition-colors z-20"></div>
        <div className="absolute bottom-0 left-0 w-2 h-2 border-l border-b border-white/20 group-hover:border-brand-accent transition-colors z-20"></div>
        <div className="absolute bottom-0 right-0 w-2 h-2 border-r border-b border-white/20 group-hover:border-brand-accent transition-colors z-20"></div>

        {/* Image Overlay */}
        <div className="relative h-48 w-full overflow-hidden">
          <div className="absolute inset-0 bg-brand-accent/0 group-hover:bg-brand-accent/10 transition-colors z-10 mix-blend-overlay"></div>
          <img 
            src={account.imageUrl} 
            alt={account.name} 
            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-brand-surface via-transparent to-transparent opacity-90" />

          {/* Status Badge */}
          <div className="absolute top-3 right-3 z-20 flex flex-col items-end gap-1">
            {isEffectivelyAvailable ? (
              <span className="inline-flex items-center px-3 py-1 bg-black/50 backdrop-blur-md border border-green-500/50 text-green-400 text-[10px] font-bold uppercase tracking-wider skew-x-[-10deg]">
                <span className="w-1.5 h-1.5 rounded-full bg-green-400 mr-2 animate-pulse" />
                Available
              </span>
            ) : (
              <div className="flex flex-col items-end gap-1">
                <span className={`inline-flex items-center px-3 py-1 backdrop-blur-md border text-[9px] font-black uppercase tracking-widest skew-x-[-10deg] shadow-[0_0_15px_rgba(0,0,0,0.5)] ${statusStyle}`}>
                  {timerLabel === 'Starts In' ? <CalendarDays className="w-3 h-3 mr-1.5" /> : <Clock className="w-3 h-3 mr-1.5 animate-pulse" />}
