// pages/UserDashboard.tsx
import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { supabase } from '../utils/supabaseClient';
import RentalCard from '../components/RentalCard';

const UserDashboard = () => {
  const { user } = useAuth();
  const [rentals, setRentals] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchRentals = async () => {
      if (!user) return; // Wait for the user to be loaded

      setIsLoading(true);
      const { data, error } = await supabase
        .from('rentals')
        .select('*')
        .eq('user_id', user.id)
        .order('start_time', { ascending: false }); // Sort by start time descending

      if (error) {
        console.error('Error fetching rentals:', error);
      } else {
        setRentals(data);
      }
      setIsLoading(false);
    };

    fetchRentals();
  }, [user]);

  if (isLoading) {
    return <div>Loading...</div>;
  }

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-2xl font-bold mb-4">Your Rentals</h1>
      {rentals.length === 0 ? (
        <p>No rentals found.</p>
      ) : (
        rentals.map((booking) => (
          <RentalCard key={booking.id} booking={booking} />
        ))
      )}
    </div>
  );
};

export default UserDashboard;
